WITH events AS (SELECT 'ADM:'||hadm_id||':ed' event_id,'A:'||hadm_id object_id,'Emergency Department Registered' activity,edregtime timestamp FROM admissions WHERE edregtime IS NOT NULL AND (1=1) UNION ALL SELECT 'ADM:'||hadm_id||':in' event_id,'A:'||hadm_id object_id,'Hospital Admitted' activity,admittime timestamp FROM admissions WHERE admittime IS NOT NULL AND (1=1) UNION ALL SELECT 'ADM:'||hadm_id||':auth' event_id,'A:'||hadm_id object_id,'Discharge Authorized' activity,discharge_authorized_at timestamp FROM admissions WHERE discharge_authorized_at IS NOT NULL AND (1=1) UNION ALL SELECT 'ADM:'||hadm_id||':out' event_id,'A:'||hadm_id object_id,'Hospital Discharged' activity,dischtime timestamp FROM admissions WHERE dischtime IS NOT NULL AND (1=1) UNION ALL SELECT 'PAT:'||subject_id||':profile' event_id,'P:'||subject_id object_id,'Patient Profile Verified' activity,profile_verified_at timestamp FROM patient_profile WHERE profile_verified_at IS NOT NULL AND (1=1) UNION ALL SELECT 'ADM:'||hadm_id||':summary' event_id,'A:'||hadm_id object_id,'Discharge Summary Signed' activity,discharge_summary_signed_at timestamp FROM admission_detail WHERE discharge_summary_signed_at IS NOT NULL AND (1=1) UNION ALL SELECT 'OH:'||history_id event_id,CASE WHEN lab_order_id IS NOT NULL THEN 'LAB:'||lab_order_id WHEN medication_order_id IS NOT NULL THEN 'MED:'||medication_order_id ELSE 'PROC:'||procedure_order_id END object_id,'Order Entered' activity,occurred_at timestamp FROM order_history WHERE occurred_at IS NOT NULL AND (action='ENTERED') UNION ALL SELECT 'OH:'||history_id event_id,CASE WHEN lab_order_id IS NOT NULL THEN 'LAB:'||lab_order_id WHEN medication_order_id IS NOT NULL THEN 'MED:'||medication_order_id ELSE 'PROC:'||procedure_order_id END object_id,'Order Reviewed' activity,occurred_at timestamp FROM order_history WHERE occurred_at IS NOT NULL AND (action='REVIEWED') UNION ALL SELECT 'OH:'||history_id event_id,CASE WHEN lab_order_id IS NOT NULL THEN 'LAB:'||lab_order_id WHEN medication_order_id IS NOT NULL THEN 'MED:'||medication_order_id ELSE 'PROC:'||procedure_order_id END object_id,'Order Cancelled' activity,occurred_at timestamp FROM order_history WHERE occurred_at IS NOT NULL AND (action='CANCELLED') UNION ALL SELECT 'LAB:'||order_id||':received' event_id,'LAB:'||order_id object_id,'Specimen Received' activity,specimen_received_at timestamp FROM lab_order WHERE specimen_received_at IS NOT NULL AND (1=1) UNION ALL SELECT 'LAB:'||order_id||':verified' event_id,'LAB:'||order_id object_id,'Lab Results Verified' activity,results_verified_at timestamp FROM lab_order WHERE results_verified_at IS NOT NULL AND (1=1) UNION ALL SELECT 'MED:'||order_id||':dispense' event_id,'MED:'||order_id object_id,'Medication Dispensed' activity,dispensed_at timestamp FROM medication_order WHERE dispensed_at IS NOT NULL AND (1=1) UNION ALL SELECT 'MED:'||order_id||':stop' event_id,'MED:'||order_id object_id,'Medication Stopped' activity,stopped_at timestamp FROM medication_order WHERE stopped_at IS NOT NULL AND (1=1) UNION ALL SELECT 'PROC:'||order_id||':prep' event_id,'PROC:'||order_id object_id,'Procedure Preparation Completed' activity,preparation_completed_at timestamp FROM procedure_order WHERE preparation_completed_at IS NOT NULL AND (1=1) UNION ALL SELECT 'LABEV:'||e.labevent_id||':chart' event_id,'LAB:'||o.order_id object_id,'Lab Measurement Charted' activity,e.charttime timestamp FROM labevents e JOIN lab_order o ON o.order_id=e.order_id WHERE e.charttime IS NOT NULL AND (1=1) UNION ALL SELECT 'LABEV:'||e.labevent_id||':result' event_id,'LAB:'||o.order_id object_id,'Lab Result Available' activity,e.storetime timestamp FROM labevents e JOIN lab_order o ON o.order_id=e.order_id WHERE e.storetime IS NOT NULL AND (1=1) UNION ALL SELECT 'EMAR:'||e.emar_id event_id,'MED:'||o.order_id object_id,'Medication Administered' activity,e.charttime timestamp FROM emar e JOIN medication_order o ON o.order_id=e.order_id WHERE e.charttime IS NOT NULL AND (e.event_txt='Administered') UNION ALL SELECT 'EMAR:'||e.emar_id event_id,'MED:'||o.order_id object_id,'Medication Not Given' activity,e.charttime timestamp FROM emar e JOIN medication_order o ON o.order_id=e.order_id WHERE e.charttime IS NOT NULL AND (e.event_txt='Not Given') UNION ALL SELECT 'PROCEV:'||e.procedureevent_id||':start' event_id,'PROC:'||o.order_id object_id,'Procedure Started' activity,e.starttime timestamp FROM procedureevents e JOIN procedure_order o ON o.order_id=e.order_id WHERE e.starttime IS NOT NULL AND (1=1) UNION ALL SELECT 'PROCEV:'||e.procedureevent_id||':end' event_id,'PROC:'||o.order_id object_id,'Procedure Completed' activity,e.endtime timestamp FROM procedureevents e JOIN procedure_order o ON o.order_id=e.order_id WHERE e.endtime IS NOT NULL AND (1=1)), orders AS (SELECT 'LAB:'||order_id order_key,hadm_id FROM lab_order UNION ALL SELECT 'MED:'||order_id,hadm_id FROM medication_order UNION ALL SELECT 'PROC:'||order_id,hadm_id FROM procedure_order), attributed AS (SELECT e.*, 'A:'||a.hadm_id admission_object, 'P:'||a.subject_id patient_object FROM events e LEFT JOIN orders c ON c.order_key=e.object_id JOIN admissions a ON e.object_id='A:'||a.hadm_id OR a.hadm_id=c.hadm_id UNION ALL SELECT e.*,NULL admission_object,e.object_id patient_object FROM events e WHERE e.object_id LIKE 'P:%') SELECT * FROM (SELECT event_id,object_id case_id,activity,timestamp FROM events WHERE object_id LIKE 'LAB:%') WHERE activity IN ('Lab Measurement Charted','Lab Result Available','Lab Results Verified') ORDER BY case_id,timestamp,event_id;
